(function(){
  var D='零一二三四五六七八九', S=['','十','百','千'], B=['','万','亿','兆'];
  var dmap={'一':1,'二':2,'两':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9};
  var umap={'十':10,'百':100,'千':1000}, bmap={'万':10000,'亿':100000000};
  function cnToNum(s){ s=String(s).replace(/[零〇]/g,''); if(s==='') return {value:0};
    var total=0,section=0,num=0;
    for(var i=0;i<s.length;i++){ var ch=s[i];
      if(dmap[ch]!==undefined){ num=dmap[ch]; }
      else if(umap[ch]!==undefined){ num=num===0?umap[ch]:num*umap[ch]; section+=num; num=0; }
      else if(bmap[ch]!==undefined){ section=(section||1)*bmap[ch]; total+=section; section=0; num=0; }
      else return {error:'无法识别: '+ch}; }
    total+=section+num; return {value:total}; }
  function numToCn(n){ n=Math.trunc(Number(n));
    if(!isFinite(n)) return {error:'无效数字'};
    if(n<0){ var r=numToCn(-n); return {value:'负'+r.value}; }
    if(n===0) return {value:'零'};
    var s=String(n), groups=[];
    for(var i=s.length;i>0;i-=4) groups.unshift(s.slice(Math.max(0,i-4),i));
    var out='';
    for(var g=0;g<groups.length;g++){ var grp=groups[g], sec='', zero=false;
      for(var p=0;p<grp.length;p++){ var digit=+grp[p], pos=grp.length-1-p;
        if(digit===0){ zero=true; } else { if(zero&&sec!=='') sec+='零'; sec+=D[digit]+S[pos]; zero=false; } }
      if(sec!=='') out+=sec+B[groups.length-1-g];
      else if(out!=='' && g<groups.length-1 && !/零$/.test(out)) out+='零';
    }
    out=out.replace(/零+/g,'零').replace(/零$/,'').replace(/^一十/,'十');
    return {value:out}; }
  var API={cnToNum:cnToNum,numToCn:numToCn};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__CnnumForge__=API;
})();
